  1	/**
  2	 * SPIKE — the connector-facing half of connector-declared entity->entity edges.
  3	 *
  4	 * NOT production placement. This exists to answer one question with running
  5	 * code rather than a design document: what does a connector actually write in
  6	 * its manifest, and how much new machinery does honouring it require?
  7	 *
  8	 * The answer is that it requires almost none. Both endpoints of an
  9	 * entity->entity edge resolve through the SAME identity machinery that
 10	 * `attributions` already uses today. So the materializer is a thin layer over
 11	 * resolution that already happens on every sync — resolve twice instead of
 12	 * once, then write one row.
 13	 *
 14	 * The declaration below deliberately mirrors `EventAttributionRule`: same
 15	 * target spec, same `autoCreate`, same identity selectors. A connector author
 16	 * who can write `attributions` can already write this.
 17	 */
 18	import type { EntityIdentitySpec } from '@lobu/connector-sdk';
 19	import type { DbClient } from '../db/client';
 20	import { getDb, pgBigintArray } from '../db/client';
 21	
 22	/**
 23	 * Proposed manifest shape, additive on `feeds_schema[feed].eventKinds[kind]`:
 24	 *
 25	 * ```ts
 26	 * eventKinds: {
 27	 *   invoice: {
 28	 *     attributions: [ ... ],            // event -> entity, unchanged
 29	 *     relationships: [                  // entity -> entity, new
 30	 *       {
 31	 *         type: 'invoice_customer',
 32	 *         from: { entityType: 'invoice',  identities: [{ namespace: 'erp_invoice',  eventPath: 'metadata.origin_id' }] },
 33	 *         to:   { entityType: 'customer', identities: [{ namespace: 'erp_customer', eventPath: 'metadata.customer_origin_id' }] },
 34	 *       },
 35	 *     ],
 36	 *   },
 37	 * }
 38	 * ```
 39	 */
 40	export type DeclaredEdgeEndpoint = {
 41	  entityType: string;
 42	  identities: EntityIdentitySpec[];
 43	};
 44	
 45	export type DeclaredEdgeRule = {
 46	  /** Relationship type slug. Resolved against the DB, never trusted from the caller. */
 47	  type: string;
 48	  from: DeclaredEdgeEndpoint;
 49	  to: DeclaredEdgeEndpoint;
 50	};
 51	
 52	function valueAtPath(item: Record<string, unknown>, path: string): string | null {
 53	  let cur: unknown = item;
 54	  for (const seg of path.split('.')) {
 55	    if (cur == null || typeof cur !== 'object') return null;
 56	    cur = (cur as Record<string, unknown>)[seg];
 57	  }
 58	  if (cur == null) return null;
 59	  const s = String(cur).trim();
 60	  return s === '' ? null : s;
 61	}
 62	
 63	/**
 64	 * Resolve one endpoint to an entity id through `entity_identities` — the same
 65	 * table `attributions` writes. Returns null when nothing resolves, which is the
 66	 * caller's signal to skip rather than to park state: the attribution pass with
 67	 * `autoCreate` is what guarantees the row exists by the time this runs.
 68	 */
 69	async function resolveEndpoint(
 70	  sql: DbClient,
 71	  orgId: string,
 72	  endpoint: DeclaredEdgeEndpoint,
 73	  item: Record<string, unknown>
 74	): Promise<number | null> {
 75	  for (const spec of endpoint.identities) {
 76	    const identifier = valueAtPath(item, spec.eventPath);
 77	    if (!identifier) continue;
 78	    const rows = await sql<{ entity_id: number }[]>`
 79	      SELECT entity_id FROM entity_identities
 80	      WHERE organization_id = ${orgId}
 81	        AND namespace = ${spec.namespace}
 82	        AND identifier = ${identifier}
 83	        AND deleted_at IS NULL
 84	      LIMIT 1
 85	    `;
 86	    if (rows.length > 0) return Number(rows[0].entity_id);
 87	  }
 88	  return null;
 89	}
 90	
 91	/**
 92	 * Resolve the relationship type FROM THE DB, never from the manifest string
 93	 * alone — the `$links` gate decision requires exactly this, so that a connector
 94	 * cannot name an authz-bearing type into existence.
 95	 */
 96	async function resolveRelationshipTypeId(
 97	  sql: DbClient,
 98	  orgId: string,
 99	  slug: string
100	): Promise<number | null> {
101	  const rows = await sql<{ id: number }[]>`
102	    SELECT id FROM entity_relationship_types
103	    WHERE organization_id = ${orgId} AND slug = ${slug} AND status = 'active'
104	    LIMIT 1
105	  `;
106	  return rows.length > 0 ? Number(rows[0].id) : null;
107	}
108	
109	export type MaterializeResult = {
110	  created: number;
111	  duplicate: number;
112	  unresolved: number;
113	  unknownType: number;
114	  /** Live edges withdrawn because the batch no longer asserts them. */
115	  retracted: number;
116	};
117	
118	/**
119	 * Honour a feed's declared edge rules for a batch of synced items.
120	 *
121	 * Runs AFTER the attribution pass, so both endpoints already exist. Writes
122	 * provenance into `metadata.derivedFrom`, which the baseline already indexes
123	 * (`idx_entity_relationships_derived_from_rule`) and which nothing else in the
124	 * repo writes.
125	 */
126	export async function materializeDeclaredEdges(params: {
127	  orgId: string;
128	  connectionId: number;
129	  ruleVersion: string;
130	  rules: DeclaredEdgeRule[];
131	  items: Array<Record<string, unknown>>;
132	  createdBy: string;
133	  /**
134	   * Withdraw edges this rule previously asserted from a from-entity that the
135	   * CURRENT batch also touches, but no longer points at the same target — the
136	   * "the invoice moved to a different customer" case. Scoped to the batch's own
137	   * from-entities, so a partial sync never retracts what it did not observe.
138	   */
139	  reconcile?: boolean;
140	  sql?: DbClient;
141	}): Promise<MaterializeResult> {
142	  const sql = params.sql ?? getDb();
143	  const out: MaterializeResult = {
144	    created: 0,
145	    duplicate: 0,
146	    unresolved: 0,
147	    unknownType: 0,
148	    retracted: 0,
149	  };
150	
151	  for (const rule of params.rules) {
152	    const typeId = await resolveRelationshipTypeId(sql, params.orgId, rule.type);
153	    if (typeId == null) {
154	      out.unknownType += params.items.length;
155	      continue;
156	    }
157	    /** from_entity_id -> the to_entity_ids THIS batch asserts for it. */
158	    const asserted = new Map<number, Set<number>>();
159	    for (const item of params.items) {
160	      const fromId = await resolveEndpoint(sql, params.orgId, rule.from, item);
161	      const toId = await resolveEndpoint(sql, params.orgId, rule.to, item);
162	      if (fromId == null || toId == null || fromId === toId) {
163	        out.unresolved += 1;
164	        continue;
165	      }
166	      const derivedFrom = {
167	        derivedFrom: {
168	          relationshipTypeId: String(typeId),
169	          ruleVersion: params.ruleVersion,
170	          connectionId: String(params.connectionId),
171	        },
172	      };
173	      const inserted = await sql<{ id: number }[]>`
174	        INSERT INTO entity_relationships (
175	          organization_id, from_entity_id, to_entity_id, relationship_type_id,
176	          metadata, confidence, source, created_by, updated_by, created_at, updated_at
177	        ) VALUES (
178	          ${params.orgId}, ${fromId}, ${toId}, ${typeId},
179	          ${sql.json(derivedFrom)}, 1.0, 'feed', ${params.createdBy}, ${params.createdBy},
180	          current_timestamp, current_timestamp
181	        )
182	        ON CONFLICT (from_entity_id, to_entity_id, relationship_type_id)
183	          WHERE deleted_at IS NULL
184	        DO NOTHING
185	        RETURNING id
186	      `;
187	      if (inserted.length > 0) out.created += 1;
188	      else out.duplicate += 1;
189	      const set = asserted.get(fromId);
190	      if (set) set.add(toId);
191	      else asserted.set(fromId, new Set([toId]));
192	    }
193	
194	    if (!params.reconcile || asserted.size === 0) continue;
195	    // Every DERIVED edge of this type, from a from-entity the batch observed,
196	    // whose target the batch no longer asserts. No separate state table is
197	    // consulted — the batch IS the snapshot, exactly as access-graph reconciles
198	    // departures.
199	    //
200	    // Deliberately NOT filtered on ruleVersion: reconcile owns the whole
201	    // derived slice for (from_entity, type). Scoping it to the current version
202	    // would strand every edge the previous version wrote the moment a connector
203	    // author bumps the rule — the stale edge stays live forever because no
204	    // later sync ever claims it. Provenance stays on the row for retraction and
205	    // audit; it is not an ownership boundary.
206	    //
207	    // A hand-authored (`source='ui'`) edge carries no `derivedFrom` and is
208	    // therefore never touched, which is the point of keying on it at all.
209	    for (const [fromId, targets] of asserted) {
210	      const stale = await sql<{ id: number }[]>`
211	        UPDATE entity_relationships
212	        SET deleted_at = current_timestamp, updated_at = current_timestamp
213	        WHERE organization_id = ${params.orgId}
214	          AND from_entity_id = ${fromId}
215	          AND relationship_type_id = ${typeId}
216	          AND deleted_at IS NULL
217	          AND metadata ? 'derivedFrom'
218	          AND NOT (to_entity_id = ANY (${pgBigintArray([...targets])}::bigint[]))
219	        RETURNING id
220	      `;
221	      out.retracted += stale.length;
222	    }
223	  }
224	  return out;
225	}
226	
227	/**
228	 * Withdraw every edge a rule version asserted. Uses only
229	 * `idx_entity_relationships_derived_from_rule`; no separate state table is
230	 * consulted, because none is needed to know what a rule wrote.
231	 */
232	export async function retractDeclaredEdges(params: {
233	  orgId: string;
234	  relationshipTypeId: number;
235	  ruleVersion: string;
236	  sql?: DbClient;
237	}): Promise<number> {
238	  const sql = params.sql ?? getDb();
239	  const rows = await sql<{ id: number }[]>`
240	    UPDATE entity_relationships
241	    SET deleted_at = current_timestamp, updated_at = current_timestamp
242	    WHERE organization_id = ${params.orgId}
243	      AND deleted_at IS NULL
244	      AND metadata ? 'derivedFrom'
245	      AND metadata -> 'derivedFrom' ->> 'relationshipTypeId' = ${String(params.relationshipTypeId)}
246	      AND metadata -> 'derivedFrom' ->> 'ruleVersion' = ${params.ruleVersion}
247	    RETURNING id
248	  `;
249	  return rows.length;
250	}

  1	/**
  2	 * SPIKE — the connector-facing half, end to end.
  3	 *
  4	 * The storage spike (`derived-edges-spike.test.ts`) proved the existing schema
  5	 * can hold connector-declared edges. This proves a connector can DECLARE them
  6	 * and that honouring the declaration needs no new machinery: the attribution
  7	 * pass resolves both endpoints, the materializer writes one row.
  8	 *
  9	 * The ERP shape throughout: an `invoice` event carries its own origin id and
 10	 * its customer's, and must become a typed `invoice_customer` edge.
 11	 */
 12	import { beforeEach, describe, expect, it } from 'vitest';
 13	import { cleanupTestDatabase, getTestDb } from '../../__tests__/setup/test-db';
 14	import {
 15	  addUserToOrganization,
 16	  createTestConnection,
 17	  createTestConnectorDefinition,
 18	  createTestOrganization,
 19	  createTestUser,
 20	} from '../../__tests__/setup/test-fixtures';
 21	import {
 22	  type DeclaredEdgeRule,
 23	  materializeDeclaredEdges,
 24	  retractDeclaredEdges,
 25	} from '../declared-edges-spike';
 26	import { applyEventAttributions, clearEntityLinkRulesCache } from '../entity-link-upsert';
 27	import { ensureMemberEntityType } from '../member-entity-type';
 28	
 29	const FEED_KEY = 'documents';
 30	const RULE_VERSION = '1';
 31	
 32	/** What the connector author writes — the proposed additive manifest field. */
 33	const DECLARED_RELATIONSHIPS: DeclaredEdgeRule[] = [
 34	  {
 35	    type: 'invoice_customer',
 36	    from: {
 37	      entityType: '$member',
 38	      identities: [{ namespace: 'erp_invoice', eventPath: 'metadata.origin_id' }],
 39	    },
 40	    to: {
 41	      entityType: '$member',
 42	      identities: [{ namespace: 'erp_customer', eventPath: 'metadata.customer_origin_id' }],
 43	    },
 44	  },
 45	];
 46	
 47	async function setupOrg(name: string) {
 48	  const org = await createTestOrganization({ name });
 49	  const user = await createTestUser();
 50	  await addUserToOrganization(user.id, org.id, 'owner');
 51	  await ensureMemberEntityType(org.id);
 52	  clearEntityLinkRulesCache();
 53	  return { org, user };
 54	}
 55	
 56	/**
 57	 * Both endpoints are minted by the EXISTING attribution surface. That is the
 58	 * whole point: the materializer adds no resolution of its own.
 59	 */
 60	async function installConnector(orgId: string) {
 61	  await createTestConnectorDefinition({
 62	    key: 'prodma',
 63	    name: 'prodma',
 64	    organization_id: orgId,
 65	    feeds_schema: {
 66	      [FEED_KEY]: {
 67	        eventKinds: {
 68	          invoice: {
 69	            attributions: [
 70	              {
 71	                role: 'belongs_to',
 72	                autoCreate: true,
 73	                target: {
 74	                  entityType: '$member',
 75	                  titlePath: 'metadata.origin_id',
 76	                  identities: [{ namespace: 'erp_invoice', eventPath: 'metadata.origin_id' }],
 77	                },
 78	              },
 79	              {
 80	                role: 'about',
 81	                autoCreate: true,
 82	                target: {
 83	                  entityType: '$member',
 84	                  titlePath: 'metadata.customer_name',
 85	                  identities: [
 86	                    { namespace: 'erp_customer', eventPath: 'metadata.customer_origin_id' },
 87	                  ],
 88	                },
 89	              },
 90	            ],
 91	          },
 92	        },
 93	      },
 94	    },
 95	  });
 96	  clearEntityLinkRulesCache();
 97	}
 98	
 99	const INVOICES = [
100	  {
101	    origin_type: 'invoice',
102	    metadata: {
103	      origin_id: 'FTR-2028-0001',
104	      customer_origin_id: 'CARI-001',
105	      customer_name: 'Akin Plastik A.S.',
106	    },
107	  },
108	  {
109	    origin_type: 'invoice',
110	    metadata: {
111	      origin_id: 'FTR-2028-0002',
112	      customer_origin_id: 'CARI-002',
113	      customer_name: 'Deniz Kalip Ltd.',
114	    },
115	  },
116	  {
117	    origin_type: 'invoice',
118	    metadata: {
119	      origin_id: 'FTR-2028-0003',
120	      customer_origin_id: 'CARI-001',
121	      customer_name: 'Akin Plastik A.S.',
122	    },
123	  },
124	];
125	
126	async function ensureRelType(orgId: string, slug: string): Promise<number> {
127	  const sql = getTestDb();
128	  const rows = await sql<{ id: number }[]>`
129	    INSERT INTO entity_relationship_types (organization_id, slug, name, status, created_at, updated_at)
130	    VALUES (${orgId}, ${slug}, ${slug}, 'active', current_timestamp, current_timestamp)
131	    RETURNING id
132	  `;
133	  return Number(rows[0].id);
134	}
135	
136	describe('SPIKE: honouring a connector-declared edge rule', () => {
137	  beforeEach(async () => {
138	    await cleanupTestDatabase();
139	    clearEntityLinkRulesCache();
140	  });
141	
142	  it('materializes declared edges from a sync batch, idempotently, then retracts them', async () => {
143	    const { org, user } = await setupOrg('materializer org');
144	    const sql = getTestDb();
145	    await installConnector(org.id);
146	    const connection = await createTestConnection({
147	      organization_id: org.id,
148	      connector_key: 'prodma',
149	      display_name: 'Prodma',
150	      created_by: user.id,
151	      createDefaultFeed: false,
152	    });
153	    const relTypeId = await ensureRelType(org.id, 'invoice_customer');
154	
155	    // --- the existing sync pass: resolves and mints both endpoints ---------
156	    await applyEventAttributions({
157	      connectorKey: 'prodma',
158	      connectionId: connection.id,
159	      feedKey: FEED_KEY,
160	      orgId: org.id,
161	      items: INVOICES,
162	    });
163	
164	    // 3 invoices + 2 distinct customers = 5 entities, from attribution alone.
165	    const entities = await sql<{ count: string }[]>`
166	      SELECT COUNT(*)::text AS count FROM entities e
167	      JOIN entity_types et ON et.id = e.entity_type_id
168	      WHERE e.organization_id = ${org.id} AND et.slug = '$member' AND e.deleted_at IS NULL
169	    `;
170	    expect(entities[0].count).toBe('5');
171	
172	    // --- the new part: honour the declaration -----------------------------
173	    const first = await materializeDeclaredEdges({
174	      orgId: org.id,
175	      connectionId: connection.id,
176	      ruleVersion: RULE_VERSION,
177	      rules: DECLARED_RELATIONSHIPS,
178	      items: INVOICES,
179	      createdBy: user.id,
180	    });
181	    expect(first).toEqual({ created: 3, duplicate: 0, unresolved: 0, unknownType: 0, retracted: 0 });
182	
183	    // Two invoices point at CARI-001; both edges exist because the SOURCE
184	    // differs. Collapsing them would lose an invoice.
185	    const edges = await sql<{ from_entity_id: number; to_entity_id: number }[]>`
186	      SELECT from_entity_id, to_entity_id FROM entity_relationships
187	      WHERE organization_id = ${org.id} AND deleted_at IS NULL
188	    `;
189	    expect(edges).toHaveLength(3);
190	    expect(new Set(edges.map((e) => Number(e.to_entity_id))).size).toBe(2);
191	
192	    // --- replay the same batch: a resync must not duplicate ---------------
193	    const replay = await materializeDeclaredEdges({
194	      orgId: org.id,
195	      connectionId: connection.id,
196	      ruleVersion: RULE_VERSION,
197	      rules: DECLARED_RELATIONSHIPS,
198	      items: INVOICES,
199	      createdBy: user.id,
200	    });
201	    expect(replay).toEqual({ created: 0, duplicate: 3, unresolved: 0, unknownType: 0, retracted: 0 });
202	
203	    const afterReplay = await sql<{ count: string }[]>`
204	      SELECT COUNT(*)::text AS count FROM entity_relationships
205	      WHERE organization_id = ${org.id} AND deleted_at IS NULL
206	    `;
207	    expect(afterReplay[0].count).toBe('3');
208	
209	    // --- retraction, by rule version alone --------------------------------
210	    const retracted = await retractDeclaredEdges({
211	      orgId: org.id,
212	      relationshipTypeId: relTypeId,
213	      ruleVersion: RULE_VERSION,
214	    });
215	    expect(retracted).toBe(3);
216	    const afterRetract = await sql<{ count: string }[]>`
217	      SELECT COUNT(*)::text AS count FROM entity_relationships
218	      WHERE organization_id = ${org.id} AND deleted_at IS NULL
219	    `;
220	    expect(afterRetract[0].count).toBe('0');
221	  });
222	
223	  it('refuses a relationship type the org has not defined', async () => {
224	    // The `$links` gate decision requires the type be resolved from the DB,
225	    // never taken from a caller-supplied string. A connector must not be able
226	    // to name an authz-bearing type into existence by writing it in a manifest.
227	    const { org, user } = await setupOrg('unknown type org');
228	    const sql = getTestDb();
229	    await installConnector(org.id);
230	    const connection = await createTestConnection({
231	      organization_id: org.id,
232	      connector_key: 'prodma',
233	      display_name: 'Prodma',
234	      created_by: user.id,
235	      createDefaultFeed: false,
236	    });
237	    await applyEventAttributions({
238	      connectorKey: 'prodma',
239	      connectionId: connection.id,
240	      feedKey: FEED_KEY,
241	      orgId: org.id,
242	      items: INVOICES,
243	    });
244	
245	    const result = await materializeDeclaredEdges({
246	      orgId: org.id,
247	      connectionId: connection.id,
248	      ruleVersion: RULE_VERSION,
249	      // Nothing created this type. A naive implementation would create it.
250	      rules: [{ ...DECLARED_RELATIONSHIPS[0], type: 'can_read' }],
251	      items: INVOICES,
252	      createdBy: user.id,
253	    });
254	    expect(result.created).toBe(0);
255	    expect(result.unknownType).toBe(3);
256	
257	    const edges = await sql<{ count: string }[]>`
258	      SELECT COUNT(*)::text AS count FROM entity_relationships
259	      WHERE organization_id = ${org.id} AND deleted_at IS NULL
260	    `;
261	    expect(edges[0].count).toBe('0');
262	    const types = await sql<{ count: string }[]>`
263	      SELECT COUNT(*)::text AS count FROM entity_relationship_types
264	      WHERE organization_id = ${org.id} AND slug = 'can_read'
265	    `;
266	    expect(types[0].count).toBe('0');
267	  });
268	
269	  it('skips an unresolvable endpoint instead of writing a half edge', async () => {
270	    const { org, user } = await setupOrg('unresolvable org');
271	    const sql = getTestDb();
272	    await installConnector(org.id);
273	    const connection = await createTestConnection({
274	      organization_id: org.id,
275	      connector_key: 'prodma',
276	      display_name: 'Prodma',
277	      created_by: user.id,
278	      createDefaultFeed: false,
279	    });
280	    await ensureRelType(org.id, 'invoice_customer');
281	
282	    // Materialize WITHOUT running the attribution pass: nothing exists yet.
283	    const result = await materializeDeclaredEdges({
284	      orgId: org.id,
285	      connectionId: connection.id,
286	      ruleVersion: RULE_VERSION,
287	      rules: DECLARED_RELATIONSHIPS,
288	      items: INVOICES,
289	      createdBy: user.id,
290	    });
291	    expect(result).toEqual({ created: 0, duplicate: 0, unresolved: 3, unknownType: 0, retracted: 0 });
292	
293	    const edges = await sql<{ count: string }[]>`
294	      SELECT COUNT(*)::text AS count FROM entity_relationships
295	      WHERE organization_id = ${org.id} AND deleted_at IS NULL
296	    `;
297	    expect(edges[0].count).toBe('0');
298	
299	    // Run the attribution pass, then materialize again — the SAME batch now
300	    // resolves. This is the ordering answer: re-running converges, and no
301	    // pending-assertion state was needed to get there.
302	    await applyEventAttributions({
303	      connectorKey: 'prodma',
304	      connectionId: connection.id,
305	      feedKey: FEED_KEY,
306	      orgId: org.id,
307	      items: INVOICES,
308	    });
309	    const second = await materializeDeclaredEdges({
310	      orgId: org.id,
311	      connectionId: connection.id,
312	      ruleVersion: RULE_VERSION,
313	      rules: DECLARED_RELATIONSHIPS,
314	      items: INVOICES,
315	      createdBy: user.id,
316	    });
317	    expect(second).toEqual({ created: 3, duplicate: 0, unresolved: 0, unknownType: 0, retracted: 0 });
318	  });
319	
320	  it('writes no edge when only ONE endpoint resolves', async () => {
321	    // The dangerous asymmetric case: the invoice exists, the customer does not
322	    // (the ERP row omitted the cari code). Both-endpoints-missing is easy to
323	    // handle by accident; this is the one that produces a dangling half edge.
324	    const { org, user } = await setupOrg('half edge org');
325	    const sql = getTestDb();
326	    await installConnector(org.id);
327	    const connection = await createTestConnection({
328	      organization_id: org.id,
329	      connector_key: 'prodma',
330	      display_name: 'Prodma',
331	      created_by: user.id,
332	      createDefaultFeed: false,
333	    });
334	    await ensureRelType(org.id, 'invoice_customer');
335	
336	    const headless = [
337	      { origin_type: 'invoice', metadata: { origin_id: 'FTR-2028-0009', customer_name: '' } },
338	    ];
339	    await applyEventAttributions({
340	      connectorKey: 'prodma',
341	      connectionId: connection.id,
342	      feedKey: FEED_KEY,
343	      orgId: org.id,
344	      items: headless,
345	    });
346	
347	    // Exactly one endpoint got minted.
348	    const invoiceSide = await sql<{ count: string }[]>`
349	      SELECT COUNT(*)::text AS count FROM entity_identities
350	      WHERE organization_id = ${org.id} AND namespace = 'erp_invoice' AND deleted_at IS NULL
351	    `;
352	    expect(invoiceSide[0].count).toBe('1');
353	    const customerSide = await sql<{ count: string }[]>`
354	      SELECT COUNT(*)::text AS count FROM entity_identities
355	      WHERE organization_id = ${org.id} AND namespace = 'erp_customer' AND deleted_at IS NULL
356	    `;
357	    expect(customerSide[0].count).toBe('0');
