  1	/**
  2	 * SPIKE — does the derived-edge provenance index still win at production scale?
  3	 *
  4	 * The earlier plan check ran against ~400 rows, where Postgres will pick an
  5	 * index for almost anything. This builds a table two orders of magnitude larger
  6	 * with a REALISTIC skew — one rule version owning the overwhelming majority of
  7	 * rows — because that is the shape that flips a planner to a sequential scan.
  8	 */
  9	import { beforeAll, describe, expect, it } from 'vitest';
 10	import { cleanupTestDatabase, getTestDb } from '../../__tests__/setup/test-db';
 11	import {
 12	  addUserToOrganization,
 13	  createTestOrganization,
 14	  createTestUser,
 15	} from '../../__tests__/setup/test-fixtures';
 16	import { ensureMemberEntityType } from '../member-entity-type';
 17	
 18	const TOTAL_EDGES = 200_000;
 19	/** The slice a retraction actually targets — rare, as a real rule bump is. */
 20	const TARGET_SLICE = 500;
 21	
 22	let orgId: string;
 23	let userId: string;
 24	let relTypeId: number;
 25	let otherTypeId: number;
 26	
 27	describe('SPIKE: derived-edge provenance at scale', () => {
 28	  beforeAll(async () => {
 29	    await cleanupTestDatabase();
 30	    const org = await createTestOrganization({ name: 'scale org' });
 31	    const user = await createTestUser();
 32	    await addUserToOrganization(user.id, org.id, 'owner');
 33	    await ensureMemberEntityType(org.id);
 34	    orgId = org.id;
 35	    userId = user.id;
 36	    const sql = getTestDb();
 37	
 38	    const [typeRow] = await sql<{ id: number }[]>`
 39	      INSERT INTO entity_relationship_types (organization_id, slug, name, status, created_at, updated_at)
 40	      VALUES (${orgId}, 'invoice_customer', 'invoice_customer', 'active', current_timestamp, current_timestamp)
 41	      RETURNING id
 42	    `;
 43	    relTypeId = Number(typeRow.id);
 44	    const [otherRow] = await sql<{ id: number }[]>`
 45	      INSERT INTO entity_relationship_types (organization_id, slug, name, status, created_at, updated_at)
 46	      VALUES (${orgId}, 'invoice_salesrep', 'invoice_salesrep', 'active', current_timestamp, current_timestamp)
 47	      RETURNING id
 48	    `;
 49	    otherTypeId = Number(otherRow.id);
 50	
 51	    const [etype] = await sql<{ id: number }[]>`
 52	      SELECT id FROM entity_types WHERE organization_id = ${orgId} AND slug = '$member' LIMIT 1
 53	    `;
 54	
 55	    // Endpoints. The unique live-triple index means every edge needs a distinct
 56	    // (from, to, type) pair, so mint enough entities to pair them off.
 57	    const endpointCount = TOTAL_EDGES / 100 + 200;
 58	    await sql`
 59	      INSERT INTO entities (organization_id, entity_type_id, name, slug, metadata, created_by, created_at, updated_at)
 60	      SELECT ${orgId}, ${Number(etype.id)}, 'scale-' || g, 'scale-' || g, '{}'::jsonb, ${userId}, current_timestamp, current_timestamp
 61	      FROM generate_series(1, ${endpointCount}) g
 62	    `;
 63	    const ids = await sql<{ id: number }[]>`
 64	      SELECT id FROM entities WHERE organization_id = ${orgId} ORDER BY id
 65	    `;
 66	    const lo = Number(ids[0].id);
 67	    const hi = Number(ids[ids.length - 1].id);
 68	
 69	    // 199_500 rows on rule version '1', 500 on '2'. `g % (hi-lo)` fans the
 70	    // from-side out so no single from-entity dominates.
 71	    await sql`
 72	      INSERT INTO entity_relationships (
 73	        organization_id, from_entity_id, to_entity_id, relationship_type_id,
 74	        metadata, confidence, source, created_by, updated_by, created_at, updated_at
 75	      )
 76	      SELECT
 77	        ${orgId},
 78	        ${lo} + (g % ${hi - lo}),
 79	        ${lo} + ((g / ${hi - lo}) % ${hi - lo}),
 80	        (CASE WHEN g % 2 = 0 THEN ${relTypeId} ELSE ${otherTypeId} END)::int,
 81	        jsonb_build_object('derivedFrom', jsonb_build_object(
 82	          'relationshipTypeId', (CASE WHEN g % 2 = 0 THEN ${relTypeId} ELSE ${otherTypeId} END)::text,
 83	          'ruleVersion', CASE WHEN g <= ${TARGET_SLICE} THEN '2' ELSE '1' END,
 84	          'connectionId', '1'
 85	        )),
 86	        1.0, 'feed', ${userId}, ${userId}, current_timestamp, current_timestamp
 87	      FROM generate_series(1, ${TOTAL_EDGES}) g
 88	      ON CONFLICT DO NOTHING
 89	    `;
 90	    await sql`ANALYZE entity_relationships`;
 91	  }, 300_000);
 92	
 93	  it('reports the table is actually large and skewed', async () => {
 94	    const sql = getTestDb();
 95	    const [row] = await sql<{ count: string }[]>`
 96	      SELECT COUNT(*)::text AS count FROM entity_relationships WHERE organization_id = ${orgId}
 97	    `;
 98	    // ON CONFLICT drops collisions; assert we still built a genuinely big table.
 99	    console.log(`[scale] entity_relationships rows: ${row.count}`);
100	    expect(Number(row.count)).toBeGreaterThan(100_000);
101	    const [skew] = await sql<{ count: string }[]>`
102	      SELECT COUNT(*)::text AS count FROM entity_relationships
103	      WHERE organization_id = ${orgId} AND metadata -> 'derivedFrom' ->> 'ruleVersion' = '1'
104	    `;
105	    expect(Number(skew.count) / Number(row.count)).toBeGreaterThan(0.9);
106	  });
107	
108	  it('the retraction sweep uses the rule index, not a sequential scan', async () => {
109	    const sql = getTestDb();
110	    const plan = await sql<{ 'QUERY PLAN': string }[]>`
111	      EXPLAIN (ANALYZE, BUFFERS)
112	      SELECT id FROM entity_relationships
113	      WHERE organization_id = ${orgId}
114	        AND deleted_at IS NULL
115	        AND metadata ? 'derivedFrom'
116	        AND metadata -> 'derivedFrom' ->> 'relationshipTypeId' = ${String(relTypeId)}
117	        AND metadata -> 'derivedFrom' ->> 'ruleVersion' = '2'
118	    `;
119	    const text = plan.map((r) => r['QUERY PLAN']).join('\n');
120	    console.log(text);
121	    expect(text).toContain('idx_entity_relationships_derived_from_rule');
122	    expect(text).not.toMatch(/Seq Scan on entity_relationships/);
123	  });
124	
125	  it('the reconcile sweep resolves by from_entity index, not a sequential scan', async () => {
126	    const sql = getTestDb();
127	    const [sample] = await sql<{ from_entity_id: number }[]>`
128	      SELECT from_entity_id FROM entity_relationships
129	      WHERE organization_id = ${orgId} LIMIT 1
130	    `;
131	    const plan = await sql<{ 'QUERY PLAN': string }[]>`
132	      EXPLAIN (ANALYZE, BUFFERS)
133	      SELECT id FROM entity_relationships
134	      WHERE organization_id = ${orgId}
135	        AND from_entity_id = ${Number(sample.from_entity_id)}
136	        AND relationship_type_id = ${relTypeId}
137	        AND deleted_at IS NULL
138	        AND metadata ? 'derivedFrom'
139	        AND NOT (to_entity_id = ANY (ARRAY[1,2,3]::bigint[]))
140	    `;
141	    const text = plan.map((r) => r['QUERY PLAN']).join('\n');
142	    console.log(text);
143	    expect(text).not.toMatch(/Seq Scan on entity_relationships/);
144	  });
145	});

