  1	/**
  2	 * PostgreSQL Database Client
  3	 *
  4	 * Provides a singleton postgres.js pool via getDb(), plus factory functions
  5	 * for creating additional connections when needed.
  6	 */
  7	
  8	import { PostgresJSDialect } from 'kysely-postgres-js';
  9	import postgres, { type Sql } from 'postgres';
 10	import type { Env } from '../index';
 11	import logger from '../utils/logger';
 12	
 13	/**
 14	 * SQL client interface — a postgres.js tagged-template client.
 15	 */
 16	export type DbQuery<T = any> = Promise<T[] & { count: number }>;
 17	
 18	export interface DbClient {
 19	  <T = any>(strings: TemplateStringsArray, ...values: unknown[]): DbQuery<T>;
 20	  unsafe<T = any>(query: string, params?: unknown[], queryOptions?: unknown): DbQuery<T>;
 21	  array<T extends string | number>(values: T[], type?: string): unknown;
 22	  json(value: unknown): unknown;
 23	  begin<T>(fn: (sql: DbClient) => Promise<T>): Promise<T>;
 24	  /**
 25	   * Run `fn` inside a SAVEPOINT. A statement that errors inside `fn` rolls back
 26	   * only to the savepoint instead of aborting the whole transaction, so callers
 27	   * can recover (e.g. retry an INSERT with a different value) or skip a single
 28	   * failing item without poisoning the surrounding `begin()` transaction. Only
 29	   * valid when the client is already inside a transaction.
 30	   */
 31	  savepoint<T>(fn: (sql: DbClient) => Promise<T>): Promise<T>;
 32	  end?: () => Promise<void>;
 33	}
