 91	/**
 92	 * Parse a value that may be a JS array or a PostgreSQL array literal
 93	 * (`{a,b,"c d"}`) into a string array. Quoted elements are unquoted and
 94	 * `\"` / `\\` escapes are resolved.
 95	 *
 96	 * The separator is only a separator OUTSIDE quotes: PostgreSQL quotes any
 97	 * element containing a comma, so `{"https://x/cb?tags=a,b"}` is ONE element.
 98	 * Splitting on every comma would shred it into two invalid ones.
 99	 */
100	export function parsePgTextArray(
101	  raw: string | string[] | null | undefined
102	): string[] {
103	  if (Array.isArray(raw)) return raw;
104	  if (raw == null || raw === '' || raw === '{}') return [];
105	  const inner =
106	    raw.startsWith('{') && raw.endsWith('}') ? raw.slice(1, -1) : raw;
107	  if (inner === '') return [];
108	  const out: string[] = [];
109	  let current = '';
110	  let inQuotes = false;
111	  let quoted = false;
112	  let escaped = false;
113	  for (const ch of inner) {
114	    if (escaped) {
115	      current += ch;
116	      escaped = false;
117	      continue;
118	    }
119	    if (ch === '\\') {
120	      escaped = true;
121	      continue;
122	    }
123	    if (ch === '"') {
124	      inQuotes = !inQuotes;
125	      if (inQuotes) quoted = true;
126	      continue;
127	    }
128	    if (ch === ',' && !inQuotes) {
129	      out.push(quoted ? current : current.trim());
130	      current = '';
131	      quoted = false;
132	      continue;
133	    }
134	    current += ch;
135	  }
136	  out.push(quoted ? current : current.trim());
137	  return out;
138	}
