143	 */
144	export function parsePgNumberArray(raw: unknown): number[] {
145	  if (Array.isArray(raw)) return raw.map(Number).filter(Number.isFinite);
146	  if (typeof raw === 'string') {
147	    return raw
148	      .replace(/[{}]/g, '')
149	      .split(',')
150	      .filter(Boolean)
151	      .map(Number)
152	      .filter(Number.isFinite);
153	  }
154	  return [];
155	}
