399	  // A present primary governs alone; otherwise every identity votes equally.
400	  const governing = primaries.length > 0 ? primaries : identities;
401	  const hits = new Set<number>();
402	  for (const id of governing) {
403	    const h = matches.get(`${id.namespace}\u0000${id.identifier}`);
404	    if (h !== undefined) hits.add(h);
405	  }
406	  if (hits.size > 1) return 'ambiguous';
407	  if (hits.size === 1) return [...hits][0];
408	  return null;
409	}
