161	    const sql = getDb();
162	    const rows = await sql`
163	      SELECT feeds_schema
164	      FROM connector_definitions
165	      WHERE key = ${params.connectorKey}
166	        AND organization_id = ${params.orgId}
167	      LIMIT 1
168	    `;
