199	/**
200	 * A single already-normalized identity ready for lookup/create — the resolved
201	 * counterpart of the declarative {@link EntityIdentitySpec} (which carries an
202	 * `eventPath` to extract FROM an event). The store-only sender path hands these
203	 * in directly, having normalized upstream.
204	 */
205	export type ResolvedIdentity = {
206	  namespace: string;
207	  identifier: string;
208	  matchOnly: boolean;
209	  primary: boolean;
210	};
