218	/**
219	 * Evaluate a rule's `createWhen` gate against the event item. Returns true (mint
220	 * allowed) when the predicate is absent or every declared condition holds; all
221	 * conditions AND together. Only gates the CREATE-on-miss branch — matching an
222	 * existing entity is never affected.
223	 */
224	function passesCreateWhen(predicate: EntityLinkPredicate | undefined, item: BatchItem): boolean {
225	  if (!predicate) return true;
226	  const value = getValueAtPath(item, predicate.path);
227	  if (predicate.equals !== undefined && value !== predicate.equals) return false;
228	  if (predicate.notEquals !== undefined && value === predicate.notEquals) return false;
229	  if (predicate.exists !== undefined) {
230	    const present = value !== undefined && value !== null && value !== '';
231	    if (present !== predicate.exists) return false;
232	  }
233	  return true;
234	}
