236	/**
237	 * Ensure each identifier value is present in `entities.metadata.aliases` — the
238	 * flat alias array the metric compiler resolves event fields against
239	 * (`metadata->'aliases'`). entity_identities serves recall/authz; aliases serve
240	 * metrics; both must carry a contact's identifiers or its per-entity metrics
241	 * silently drop.
242	 *
243	 * Done as ONE atomic UPDATE that unions the row's existing aliases with the new
244	 * identifiers in SQL — a JS read-modify-write would let concurrent ingests on
245	 * the same entity clobber each other's additions. The `@>` guard means the write
246	 * is skipped (0 rows) when every identifier is already present, so repeat
247	 * messages from a known, fully-aliased sender cost only a PK lookup. Passing the
248	 * entity's full identifier set (not just freshly-inserted ones) also repairs a
249	 * legacy entity whose `entity_identities` predate aliases-on-create.
250	 */
251	async function ensureAliases(
252	  sql: DbClient,
253	  params: { orgId: string; entityId: number; identifiers: string[] }
254	): Promise<void> {
255	  if (params.identifiers.length === 0) return;
256	  await sql`
257	    UPDATE entities
258	    SET metadata = jsonb_set(
259	          COALESCE(metadata, '{}'::jsonb),
260	          '{aliases}',
261	          (
262	            SELECT to_jsonb(array_agg(DISTINCT a))
263	            FROM (
264	              SELECT jsonb_array_elements_text(COALESCE(metadata->'aliases', '[]'::jsonb)) AS a
265	              UNION
266	              SELECT unnest(${pgTextArray(params.identifiers)}::text[]) AS a
267	            ) u
268	          )
269	        ),
270	        updated_at = current_timestamp
271	    WHERE id = ${params.entityId}
