354	    SELECT ei.entity_id, ei.namespace, ei.identifier
355	    FROM entity_identities ei
356	    JOIN entities e ON e.id = ei.entity_id
357	    WHERE ei.organization_id = ${params.orgId}
358	      AND ei.deleted_at IS NULL
359	      AND e.deleted_at IS NULL
360	      AND (ei.namespace, ei.identifier) IN (
361	        SELECT ns, ident FROM unnest(${pgTextArray(namespaces)}::text[], ${pgTextArray(identifiers)}::text[]) AS u(ns, ident)
