 47	export function normalizeEmail(raw: string | null | undefined): string | null {
 48	  if (typeof raw !== 'string') return null;
 49	  const trimmed = raw.trim().toLowerCase();
 50	  if (!trimmed) return null;
 51	  const atIndex = trimmed.indexOf('@');
 52	  if (atIndex <= 0 || atIndex === trimmed.length - 1) return null;
 53	  if (trimmed.indexOf('@', atIndex + 1) !== -1) return null;
 54	  const local = trimmed.slice(0, atIndex);
 55	  const domain = trimmed.slice(atIndex + 1);
 56	  if (!local || !domain) return null;
 57	  if (domain.indexOf('.') === -1) return null;
 58	  if (/\s/.test(trimmed)) return null;
 59	  return trimmed;
 60	}
